mapper.select:
select r.review_id, r.vehicle_id, r.user_id, r.order_id, r.rating, r.content, r.image_url, r.is_anonymous, r.status, r.create_time, u.nick_name, v.model_name as vehicle_name from stad_vehicle_review r left join sys_user u on r.user_id = u.user_id left join stad_vehicle v on r.vehicle_id = v.vehicle_id
AND r.rating = #{rating}
AND r.vehicle_id = #{vehicleId}
AND (r.content like concat('%',#{keyword},'%') OR v.model_name like concat('%',#{keyword},'%'))
AND r.status = '0'
order by r.create_time desc
